import unittest
from billing import calc_tax, make_invoice


class T(unittest.TestCase):
    def test_tax(self):
        self.assertEqual(calc_tax(1000), 100)
        self.assertEqual(calc_tax(1005, 0.5), 502)

    def test_invoice(self):
        self.assertEqual(make_invoice(2000), {"amount": 2000, "tax": 200, "total": 2200})
